/// Copy a vector of chars by pushing each element in turn.
/// 
/// Specification:
///   - No pre‐conditions (always callable).
///   - Ensures that the result has the same length as the original.
///   - Ensures that for every index i, result[i] == t[i].
#[requires(true)]
#[ensures(result.len() == old(t.len()))]
#[ensures(
    forall(|i: usize| 
        i < old(t.len()) ==> result[i] == t[i]
    )
)]
fn solve(t: Vec<char>) -> Vec<char> {
    // Pre‐allocate a new vector with the same capacity as the input
    let mut out = Vec::with_capacity(t.len());

    // Traverse the input from start to end, pushing each character
    for c in t {
        out.push(c);
    }

    out
}

